#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include "../eikonal-cuda/kernel.cu"
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<double>load(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);size_t n=f.tellg();f.seekg(0);std::vector<double>v(n/8);f.read((char*)v.data(),n);return v;}
template<class T>struct Buf{T*d;std::vector<T>h;T sentinel;Buf(const std::vector<T>&v,T s):sentinel(s){h.assign(v.size()+8,s);std::copy(v.begin(),v.end(),h.begin()+4);ck(cudaMalloc(&d,h.size()*sizeof(T)));reset();}T*ptr(){return d+4;}void reset(){ck(cudaMemcpy(d,h.data(),h.size()*sizeof(T),cudaMemcpyHostToDevice));}std::vector<T>get(){std::vector<T>r(h.size());ck(cudaMemcpy(r.data(),d,r.size()*sizeof(T),cudaMemcpyDeviceToHost));return r;}void capture(std::vector<double>&out,bool&ok,bool unchanged=false){auto r=get();if(unchanged)ok&=r==h;for(int j=0;j<4;j++)ok&=r[j]==sentinel;for(size_t j=r.size()-4;j<r.size();j++)ok&=r[j]==sentinel;for(auto v:r)out.push_back(double(v));}};
struct Case{int n,it;Buf<double>*speed,*a,*b;Buf<unsigned char>*mask,*con,*vol;Buf<unsigned>*list;};
int solve(Case&c,int&processed){int blocks=c.n*c.n*c.n/64,nx=c.n/4;std::vector<unsigned>list(blocks,0xdeadbeef);std::vector<unsigned char>listed(blocks,0),vol(blocks,0);list[0]=0;listed[0]=vol[0]=1;int active=1,iter=0;processed=0;
 while(active){if(++iter>1000){fprintf(stderr,"IterationLimit\n");exit(3);}processed+=active;ck(cudaMemcpy(c.list->ptr(),list.data(),active*4,cudaMemcpyHostToDevice));run_solver<<<active,dim3(4,4,4)>>>(c.speed->ptr(),(bool*)c.mask->ptr(),c.a->ptr(),c.b->ptr(),(bool*)c.con->ptr(),c.list->ptr(),c.n,c.n,c.n,c.it,active);run_reduction<<<active,dim3(4,4,2)>>>((bool*)c.con->ptr(),(bool*)c.vol->ptr(),c.list->ptr(),active);ck(cudaMemcpy(vol.data(),c.vol->ptr(),blocks,cudaMemcpyDeviceToHost));int old=active;
 for(int i=0;i<old;i++){unsigned cur=list[i];if(!vol[cur]){unsigned nb[]={cur<unsigned(nx*nx)?cur:cur-nx*nx,cur+nx*nx>=unsigned(blocks)?cur:cur+nx*nx,cur<unsigned(nx)?cur:cur-nx,cur+nx>=unsigned(blocks)?cur:cur+nx,cur%nx==0?cur:cur-1,(cur+1)%nx==0?cur:cur+1};for(auto v:nb)if(!listed[v]){listed[v]=1;list[active++]=v;}}}
 ck(cudaMemcpy(c.list->ptr(),list.data(),active*4,cudaMemcpyHostToDevice));run_check_neighbor<<<active,dim3(4,4,4)>>>(c.speed->ptr(),(bool*)c.mask->ptr(),c.b->ptr(),c.a->ptr(),(bool*)c.con->ptr(),c.list->ptr(),c.n,c.n,c.n,old,active);run_reduction<<<active,dim3(4,4,2)>>>((bool*)c.con->ptr(),(bool*)c.vol->ptr(),c.list->ptr(),active);ck(cudaMemcpy(vol.data(),c.vol->ptr(),blocks,cudaMemcpyDeviceToHost));active=0;for(int i=0;i<blocks;i++){listed[i]=vol[i]?1:0;if(vol[i])list[active++]=i;}}
 ck(cudaDeviceSynchronize());return iter;}
int main(){auto f=load(EK_FIXTURE),oracle=load(EK_ORACLE);std::vector<Case>cs;size_t off=0;while(off<f.size()){int n=f[off],it=f[off+1];off+=3;int N=n*n*n,nb=N/64;std::vector<double>speed(f.begin()+off,f.begin()+off+N);off+=N;std::vector<double>init(f.begin()+off,f.begin()+off+N);off+=N;std::vector<unsigned char>v(nb,0);v[0]=1;std::vector<unsigned>l(nb,0xdeadbeef);l[0]=0;cs.push_back({n,it,new Buf<double>(speed,-8192.25),new Buf<double>(init,-8192.25),new Buf<double>(init,-8192.25),new Buf<unsigned char>(std::vector<unsigned char>(N,1),0),new Buf<unsigned char>(std::vector<unsigned char>(N,1),0),new Buf<unsigned char>(v,0),new Buf<unsigned>(l,0xdeadbeef)});}
 auto reset=[](Case&c){c.a->reset();c.b->reset();c.con->reset();c.vol->reset();c.list->reset();};for(auto&c:cs){int proc;solve(c,proc);}
 for(int trial=1;trial<=5;trial++){auto out=f;bool ok=true;double tm=0,err=0;size_t oi=0;for(auto&c:cs){reset(c);ck(cudaDeviceSynchronize());int processed;auto st=std::chrono::steady_clock::now();int iter=solve(c,processed);tm+=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count();auto sol=c.a->get();int N=c.n*c.n*c.n;for(int j=0;j<N;j++){double x=sol[j+4],e=fabs(x-oracle[oi+j]);err=fmax(err,e);ok&=std::isfinite(x)&&x>=0&&e<=1e-5+1e-5*fabs(oracle[oi+j]);}ok&=sol[4]==0;oi+=N;c.speed->capture(out,ok,true);c.mask->capture(out,ok,true);c.a->capture(out,ok);c.b->capture(out,ok);c.con->capture(out,ok);c.vol->capture(out,ok);c.list->capture(out,ok);out.push_back(iter);out.push_back(processed);}std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream z(path,std::ios::binary);z.write((char*)out.data(),out.size()*8);z.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"timing_region\":\"sum3_full_active_list_FIM_solver_host_scheduling_copies_complete\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,tm,ok?"true":"false",out.size(),err,path.c_str(),out.size());if(!ok)return 3;}}
